<?php

const MOD = 998244353;
const NN = 5000;

$factor = [];
$primes = [];

function comb($m, $n) {
    global $factor, $primes;
    $res = 1;
    $fnm = $factor[$n];
    foreach ($factor[$m] as $i => $x) {
        $fnm[$i] += $x;
    }
    for ($w = 1; $w <= $m; $w++) {
        $r = 1;
        foreach ($primes as $i => $p) {
            for ($pw = $fnm[$i] - $factor[$w][$i] - $factor[$n - $w][$i] -
                $factor[$m - $w][$i]; $pw > 0; $pw >>= 1) {
                if (($pw & 1) == 1) {
                    $r = $r * $p % MOD;
                }
                $p = $p * $p % MOD;
            }
        }
        $res += $r;
    }
    return $res % MOD;
}

function main() {
    global $factor, $primes;

    $input = stream_get_contents(STDIN);
    $tokens = preg_split('/\s+/', trim($input));
    $abc = [(int)$tokens[0], (int)$tokens[1], (int)$tokens[2]];
    sort($abc);

    $sieve = array_fill(0, NN + 1, false);
    $sieve[0] = true;
    $sieve[1] = true;
    for ($p = 0; $p <= NN; $p++) {
        if (!$sieve[$p]) {
            $primes[] = $p;
            for ($q = $p * $p; $q <= NN; $q += $p) {
                $sieve[$q] = true;
            }
        }
    }

    $np = count($primes);
    for ($j = 0; $j <= NN; $j++) {
        $factor[$j] = array_fill(0, $np, 0);
    }

    foreach ($primes as $i => $p) {
        for ($pp = $p; $pp <= NN; $pp *= $p) {
            for ($j = $pp; $j <= NN; $j += $pp) {
                $factor[$j][$i]++;
            }
        }
    }

    $a = $factor[0];
    for ($j = 0; $j <= NN; $j++) {
        foreach ($a as $i => $x) {
            $factor[$j][$i] += $x;
        }
        $a = $factor[$j];
    }

    echo comb($abc[0], $abc[1]) * comb($abc[0], $abc[2]) % MOD * comb($abc[1], $abc[2]) % MOD, "\n";
}

main();
